import {STORAGE_KEY,freshDraft,cleanDraft,scorePathways,themeNames} from './engine.js?v=0.17.0';
import {lifestyleChoices,setLifestyleChoice,confirmLifestyle,lifestyleSnapshot} from './lifestyle-state.js';
import {onetQuestions,onetResponseOptions,onetInstrument,scoreOnetInterest} from './onet-assessment.js';
import {money} from './lifestyle-ui.js';
import {summarizeEarnings} from './earnings.js';

export const sampleStudent={name:'Jordan',description:'A fictional grade 11 student who likes figuring things out, building things and trying visual ideas. Jordan is considering college, including a possible transfer route, and is not ready to choose a profession.'};
export const journeySteps=[
 {route:'journey',label:'Meet Jordan',copy:'A college direction, with several futures still open.'},
 {route:'lifestyle/0',label:'Lifestyle choices',copy:'Replay Jordan’s nine everyday choices. Answers are already selected; continue through each one or jump ahead.'},
 {route:'lifestyle/summary',label:'Budget & goal',copy:'Review the planning amounts, then see the income needed to support this future-life picture.'},
 {route:'journey/interests',label:'Interest profiler',copy:'Inspect all 60 fictional responses and the six scores calculated by the unchanged O*NET profiler.'},
 {route:'subjects',label:'Subject reflection',copy:'Optional: try eight original course and project prompts, or explicitly load Jordan’s new fictional choices. Skipping retains the original interest order.'},
 {route:'pathways',label:'College pathways',copy:'Explore four starting points or six broad areas, then keep a creative alternative open as a personal choice.'},
 {route:'compare',label:'Earnings & tradeoffs',copy:'Compare the three college directions against the same budget, without selecting a profession.'},
 {route:'plan',label:'Next-step plan',copy:'Leave with coursework, program and cost questions to investigate, rather than a final job title.'}
];
const responses={R:[4,3,5,4,4,4,5,3,4,3],I:[5,5,4,5,4,5,5,4,4,5],A:[3,4,3,2,5,4,3,2,3,4],S:[3,3,2,3,3,3,2,2,3,3],E:[2,2,3,3,4,2,3,2,2,3],C:[5,4,4,3,4,3,4,3,4,3]};
const choices={home:2,transport:2,groceries:1,dining:1,travel:2,entertainment:1,recreation:2,clothing:1,saving:2};
export function makeSampleDraft(){
 const draft=freshDraft(),counts={R:0,I:0,A:0,S:0,E:0,C:0};
 for(const q of onetQuestions)draft.answers[q.id]=responses[q.theme][counts[q.theme]++];
 for(const q of lifestyleChoices)setLifestyleChoice(draft.lifestyle,q.id,choices[q.id]);
 confirmLifestyle(draft.lifestyle);
 draft.saved=['software','electrical','design'];
 draft.notes={software:'I want to compare computer science with an associate-to-bachelor’s transfer plan. Which credits transfer, and can I try programming before deciding?',electrical:'Circuits and hardware appeal to me. Compare first-year calculus and physics, lab access and the full engineering degree route.',design:'Keep this creative alternative open. Try a small digital design project and compare portfolio expectations, paid placements and graduate outcomes.'};
 return draft;
}
export function sampleInterest(draft){return scoreOnetInterest({profileJourney:{officialInterest:{instrument:onetInstrument.id,version:onetInstrument.version,answers:draft.answers}}});}
export function draftForMode({sample,storage,ids}){if(sample)return makeSampleDraft();return cleanDraft(JSON.parse(storage.getItem(STORAGE_KEY)),ids);}
export function persistForMode({sample,storage,key,draft}){if(sample)return;storage.setItem(key,JSON.stringify(draft));}
const h=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const button=(label,route,secondary=false)=>`<a class="button${secondary?' secondary':''}" href="#/${route}">${label}</a>`;
export function journeyStepFor(route){if(route.startsWith('subjects'))return 4;if(route==='journey/interests'||route.startsWith('interests'))return 3;if(route.startsWith('lifestyle/summary'))return 2;if(route.startsWith('lifestyle'))return 1;if(route.startsWith('pathways')||route.startsWith('path/'))return 5;if(route==='compare'||route==='shortlist')return 6;if(route==='plan')return 7;return 0;}
export function journeyBanner(route){const i=journeyStepFor(route),step=journeySteps[i];return`<aside class="journey-guide" aria-label="Fictional student journey"><div class="journey-guide-top"><div><strong>Fictional sample · Jordan</strong><p>A completed journey to replay. Edits last only in this tab; reloading restarts the sample. Your own saved draft is untouched.</p></div><a class="text-link" href="./?v=0.17.0#/">Exit sample & return to my draft ↗</a></div><nav class="journey-steps" aria-label="Sample journey steps">${journeySteps.map((s,n)=>`<a href="#/${s.route}" ${n===i?'aria-current="step"':''}><span>${n+1}</span>${s.label}</a>`).join('')}</nav><div class="journey-guide-bottom"><p><strong>${i+1} of ${journeySteps.length} · ${step.label}.</strong> ${step.copy}</p>${i<journeySteps.length-1?`<a class="text-link" href="#/${journeySteps[i+1].route}">Next: ${journeySteps[i+1].label} →</a>`:'<a class="text-link" href="#/journey">Replay from the beginning ↗</a>'}</div></aside>`;}
function choiceList(draft){return lifestyleChoices.map((q,i)=>{const options=q.id==='home'&&draft.lifestyle.builder.homeMode==='own'?q.ownOptions:q.options,answer=options[draft.lifestyle.builder.choices[q.id]];return`<div><span>${h(q.question)}</span><a href="#/lifestyle/${i}">${answer?h(answer.title):'Not answered'} ↗</a></div>`;}).join('');}
export function journeyOverview(draft,data,earnings){
 const g=lifestyleSnapshot(draft.lifestyle),profile=sampleInterest(draft),suggested=scorePathways(data.pathways,profile).slice(0,4),goal=g.status==='ready'&&g.confirmed;
 return`<div class="wrap"><section class="page-intro"><span class="eyebrow">A complete fictional student journey</span><h1>Follow Jordan.<br>Keep the future open.</h1><p class="lede">${h(sampleStudent.description)}</p><p>This is a completed example, ready to replay. It uses the same questionnaire, scoring, pathway engine and budget comparisons as the student experience. The story and responses are invented; they are not an outcome validation study.</p><div class="actions">${button('Start with lifestyle choices →','lifestyle/0')}${button('Jump to the pathway comparison','compare',true)}</div></section><div class="journey-overview-grid"><section class="panel"><span class="eyebrow">1 · Picture a future life</span><h2>A modest place.<br>Room for interests.</h2><p>Jordan pictures renting their own space, a reliable used car, time for hobbies, an annual trip and regular saving. This is a future adult lifestyle, separate from college attendance costs.</p><div class="choice-summary">${choiceList(draft)}</div></section><div><section class="panel"><span class="eyebrow">2 · Turn choices into a goal</span>${goal?`<h2>${money(g.range.low)}<span class="goal-unit">annual income before tax, about the minimum for this budget</span></h2><p><strong>${money(g.range.high)}</strong> adds 20% breathing room. Spending, cash saving and health total <strong>${money(g.total)} / month</strong>. Taxes and retirement are handled separately.</p><p class="subtle">Austin employee illustration with the existing 2026 tax model. Car down payment: ${money(g.result.carUpfront)} upfront.</p>`:'<h2>Review the edited budget.</h2><p>The sample budget needs confirmation before comparisons return.</p>'}${button('Inspect the budget & assumptions','lifestyle/summary',true)}</section><section class="panel"><span class="eyebrow">3 · Reflect on interests</span><h3>${profile.answered} of 60 fictional responses</h3><p>Scores are calculated from the actual item responses. The interest reflection explores enjoyment of activities, not ability or a guaranteed career match.</p>${button('See the profiler & responses','journey/interests',true)}</section></div></div><section class="panel"><span class="eyebrow">4 · Look for college beginnings</span><h2>Suggestions are starting points.</h2><p>Before the optional subject reflection, the broad-interest starting points are ${suggested.map(p=>h(p.title)).join('; ')}. Jordan can still explore all ${data.pathways.length} pathways across ${data.areas.length} broad areas, covering ${new Set(data.pathways.flatMap(p=>p.occupations)).size} occupation destinations under the college-exploration policy. Income has no effect on this order.</p><p>The original story shortlists <strong>Computer science & software</strong> and <strong>Electrical & computer engineering</strong>, then deliberately keeps <strong>Visual design & digital experiences</strong> as a creative alternative. The shortlist is an editorial story choice, not the profiler’s top three or an automatic financial recommendation.</p><p>Now try eight optional course and project questions to refine those starting points. Jordan’s new subject choices are loaded only when you explicitly request them.</p>${button('Try the subject reflection','subjects',true)} ${button('Explore the pathway suggestions','pathways',true)}<p style="margin-top:20px">Keep exploring the expanded library: <a href="#/path/engineering">engineering across science &amp; systems</a> or <a href="#/path/applied-technology">engineering technology, manufacturing &amp; repair</a>. These are additional directions to investigate, not extra automatic matches.</p></section><section class="panel"><span class="eyebrow">5 · Compare earning possibilities</span><h2>One budget.<br>Several possible routes.</h2><p>Compare the selected qualifying-route earning examples below. Further-study and experienced destinations stay separate. These are 2025 Austin occupational examples, not earnings distributions for college majors.</p><div class="journey-evidence"><table><caption>Fictional sample · current shortlist · lower-paid-worker examples</caption><thead><tr><th scope="col">College pathway</th><th scope="col">Budget covered</th><th scope="col">With breathing room</th></tr></thead><tbody>${draft.saved.map(id=>{const p=data.pathways.find(x=>x.id===id);if(!p)return'';const s=summarizeEarnings(earnings.pathways[id]||[],draft.lifestyle),count=s.entry.range?.count||0;return`<tr><th scope="row">${h(p.title)}</th><td>${goal&&count?s.entry.covers+' of '+count:'Review budget / data'}</td><td>${goal&&count?s.entry.breathingRoom+' of '+count:'Review budget / data'}</td></tr>`;}).join('')}</tbody></table></div><p class="subtle">Counts describe only the selected examples, not the probability that a student will earn enough. “Lower-paid-worker” means the lowest-third average within each occupation; it is not an observed new-graduate starting salary.</p>${button('Compare pathways, budgets & earnings →','compare')}</section><section class="panel"><span class="eyebrow">6 · Leave with experiments to try</span><h3>Jordan’s next move is to learn more.</h3><p>Try a small coding project, a beginner circuit and a digital design exercise. Compare two real programs for each direction, transfer credit, total net cost and published graduate outcomes. Jordan has not chosen a major, college or profession.</p>${button('Open Jordan’s next-step plan','plan',true)}</section></div>`;
}
export function journeyInterests(draft){const p=sampleInterest(draft),order=['R','I','A','S','E','C'];return`<div class="wrap"><section class="page-intro"><span class="eyebrow">The same 60-item interest profiler</span><h1>Activities first.<br>A pattern to explore.</h1><p class="lede">These are Jordan’s invented responses to the unchanged O*NET® Interest Profiler. All ${p.answered} answers are visible below; the usual scoring function calculates the results.</p></section><section class="panel"><h2>Six broad interests</h2><div class="journey-score-grid">${order.map((theme,i)=>`<div><span>${h(themeNames[i])}</span><strong>${p.groups[theme].raw===null?'Incomplete':p.groups[theme].raw+' / 40'}</strong><div class="journey-meter" aria-hidden="true"><span style="width:${(p.groups[theme].raw||0)/40*100}%"></span></div></div>`).join('')}</div><p class="subtle">Raw theme totals sum ten answers minus one per answer. These are not fit percentages, ability scores or rankings of how valuable an interest is. The story treats hands-on, investigative and creative routes as possibilities to explore; all pathways stay open.</p><div class="actions">${button('Replay the actual profiler screens','interests/0',true)}${button('Try optional subject reflection →','subjects')}${button('Skip to pathways','pathways',true)}</div></section><details class="panel"><summary>Inspect all 60 fictional answers</summary><p>Original item wording and response labels are preserved. Click a question number to review it in the student questionnaire.</p><ol class="journey-answer-list">${onetQuestions.map((q,i)=>`<li><a href="#/interests/${i}" aria-label="Review question ${i+1}">${i+1}</a><span>${h(q.text)}</span><strong>${h(onetResponseOptions.find(o=>o.value===draft.answers[q.id])?.label||'Not answered')}</strong></li>`).join('')}</ol></details><p class="subtle">${h(onetInstrument.attribution)}</p></div>`;}
